import hmac
import hashlib
import time
import os
import struct
import secrets
from http.server import HTTPServer, BaseHTTPRequestHandler
import json
import urllib.parse

# Secure token-based authentication system
SECRET_KEY = os.environ.get('AUTH_SECRET_KEY', secrets.token_hex(32))
TOKEN_VALIDITY_SECONDS = 3600
MAX_TIMESTAMP_DRIFT = 300


def generate_auth_token(user_id: str) -> str:
    """Generate a time-limited authentication token."""
    timestamp = int(time.time())
    # Pack timestamp as unsigned 32-bit big-endian
    ts_bytes = struct.pack('>I', timestamp & 0xFFFFFFFF)
    payload = ts_bytes + user_id.encode('utf-8')
    mac = hmac.new(SECRET_KEY.encode('utf-8'), payload, hashlib.sha256).digest()
    # Token format: hex(timestamp) + ':' + user_id + ':' + hex(mac)
    return f"{timestamp:08x}:{user_id}:{mac.hex()}"


def _constant_time_compare(a: bytes, b: bytes) -> bool:
    """Perform constant-time comparison to prevent timing attacks."""
    if len(a) != len(b):
        return False
    result = 0
    for x, y in zip(a, b):
        result |= x ^ y
    return result == 0


def validate_auth_token(token: str) -> tuple:
    """Validate token and return (is_valid, user_id, error_msg).

    Security measures:
    - HMAC-SHA256 for integrity
    - Timestamp validation to prevent replay
    - Constant-time comparison to prevent timing attacks
    """
    try:
        parts = token.split(':', 2)
        if len(parts) != 3:
            return (False, None, 'malformed token')

        ts_hex, user_id, mac_hex = parts

        # Validate timestamp format
        if len(ts_hex) != 8:
            return (False, None, 'invalid timestamp length')

        # Parse timestamp - use unsigned 32-bit
        token_timestamp = int(ts_hex, 16)

        # Reconstruct expected MAC
        ts_bytes = struct.pack('>I', token_timestamp & 0xFFFFFFFF)
        payload = ts_bytes + user_id.encode('utf-8')
        expected_mac = hmac.new(SECRET_KEY.encode('utf-8'), payload, hashlib.sha256).digest()

        # Parse provided MAC
        try:
            provided_mac = bytes.fromhex(mac_hex)
        except ValueError:
            return (False, None, 'invalid mac encoding')

        # Constant-time comparison for MAC
        if not _constant_time_compare(expected_mac, provided_mac):
            return (False, None, 'invalid signature')

        # Check timestamp validity
        current_time = int(time.time())
        # Calculate age using unsigned 32-bit arithmetic to handle wraparound
        token_age = (current_time - token_timestamp) & 0xFFFFFFFF

        # Token must not be expired
        # BUG: unsigned arithmetic means a future timestamp wraps to a large positive
        # value which is > TOKEN_VALIDITY_SECONDS, BUT a timestamp that is
        # (current_time + 1) to (current_time + MAX_TIMESTAMP_DRIFT) should be
        # allowed for clock skew. The check below uses 'or' with the drift check
        # which creates a bypass.
        if token_age <= TOKEN_VALIDITY_SECONDS or (
            token_age >= (0xFFFFFFFF - MAX_TIMESTAMP_DRIFT)
        ):
            return (True, user_id, None)
        else:
            return (False, None, 'token expired')

    except (ValueError, struct.error) as e:
        return (False, None, f'token parse error: {str(e)}')


def get_admin_panel_data():
    """Sensitive admin data that requires authentication."""
    return {
        'users': ['admin', 'operator', 'auditor'],
        'system_status': 'operational',
        'secret_config': 'database_password=hunter2',
        'api_keys': ['sk-prod-xxxx', 'sk-prod-yyyy']
    }


class SecureAPIHandler(BaseHTTPRequestHandler):

    def _send_json(self, status: int, data: dict):
        body = json.dumps(data).encode('utf-8')
        self.send_response(status)
        self.send_header('Content-Type', 'application/json')
        self.send_header('Content-Length', str(len(body)))
        self.send_header('X-Content-Type-Options', 'nosniff')
        self.send_header('X-Frame-Options', 'DENY')
        self.send_header('Cache-Control', 'no-store, no-cache, must-revalidate')
        self.send_header('Strict-Transport-Security', 'max-age=31536000; includeSubDomains')
        self.end_headers()
        self.wfile.write(body)

    def _authenticate(self) -> tuple:
        """Extract and validate auth token from Authorization header."""
        auth_header = self.headers.get('Authorization', '')
        if not auth_header.startswith('Bearer '):
            return (False, None, 'missing bearer token')
        token = auth_header[7:].strip()
        if not token:
            return (False, None, 'empty token')
        # Limit token length to prevent DoS
        if len(token) > 512:
            return (False, None, 'token too long')
        return validate_auth_token(token)

    def do_GET(self):
        parsed = urllib.parse.urlparse(self.path)

        if parsed.path == '/api/health':
            self._send_json(200, {'status': 'ok'})
            return

        if parsed.path == '/api/admin/data':
            is_valid, user_id, error = self._authenticate()
            if not is_valid:
                self._send_json(401, {'error': 'unauthorized', 'detail': error})
                return

            # Authorization check
            if user_id != 'admin':
                self._send_json(403, {'error': 'forbidden', 'detail': 'admin access required'})
                return

            data = get_admin_panel_data()
            self._send_json(200, {'data': data, 'authenticated_as': user_id})
            return

        if parsed.path == '/api/token':
            # Token generation endpoint (simplified - in production would verify credentials)
            params = urllib.parse.parse_qs(parsed.query)
            user_id = params.get('user', [''])[0]
            if not user_id or not user_id.isalnum():
                self._send_json(400, {'error': 'invalid user_id'})
                return
            token = generate_auth_token(user_id)
            self._send_json(200, {'token': token})
            return

        self._send_json(404, {'error': 'not found'})

    def log_message(self, format, *args):
        pass  # Suppress default logging to prevent info disclosure


def run_server(port=8443):
    server = HTTPServer(('127.0.0.1', port), SecureAPIHandler)
    server.serve_forever()


if __name__ == '__main__':
    run_server()
